-- statement
UPDATE citizenchain_download_publications SET version_tag=json_extract(?1,'$.input.publication.version_tag'),source_sha=json_extract(?1,'$.input.publication.source_sha'),asset_name=json_extract(?1,'$.input.publication.asset_name'),asset_sha256=json_extract(?1,'$.input.publication.asset_sha256'),revision=revision+1,published_at=CASE WHEN json_type(?1,'$.input.publication')='null' THEN NULL ELSE json_extract(?1,'$.now') END WHERE platform=json_extract(?1,'$.platform') AND revision=json_extract(?1,'$.input.expected_revision') AND revision<9007199254740991 AND NOT(version_tag IS json_extract(?1,'$.input.publication.version_tag') AND source_sha IS json_extract(?1,'$.input.publication.source_sha') AND asset_name IS json_extract(?1,'$.input.publication.asset_name') AND asset_sha256 IS json_extract(?1,'$.input.publication.asset_sha256'));
-- statement
INSERT INTO citizenchain_download_publications(platform) SELECT NULL WHERE NOT EXISTS(SELECT 1 FROM citizenchain_download_publications WHERE platform=json_extract(?1,'$.platform') AND version_tag IS json_extract(?1,'$.input.publication.version_tag') AND source_sha IS json_extract(?1,'$.input.publication.source_sha') AND asset_name IS json_extract(?1,'$.input.publication.asset_name') AND asset_sha256 IS json_extract(?1,'$.input.publication.asset_sha256'));
